import{_ as r,o as t,a,b as o}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"AI Core SIMT编程","link":"/guide/programming_guide/programming_model/ai_core_simt_programming/ai_core_simt_programming"},{"text":"概述","link":"/guide/programming_guide/programming_model/ai_core_simt_programming/overview"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/ai_core_simt_programming/overview.md","filePath":"guide/programming_guide/programming_model/ai_core_simt_programming/overview.md","outlineHeaders":[{"level":2,"title":"引言","slug":"引言","link":"#引言"},{"level":2,"title":"异构并行计算核心模型：SIMT编程范式","slug":"异构并行计算核心模型：SIMT编程范式","link":"#异构并行计算核心模型：SIMT编程范式"},{"level":2,"title":"硬件底层支撑：SIMT单元架构与内存层级","slug":"硬件底层支撑：SIMT单元架构与内存层级","link":"#硬件底层支撑：SIMT单元架构与内存层级"},{"level":3,"title":"核心硬件组件","slug":"核心硬件组件","link":"#核心硬件组件"},{"level":3,"title":"SIMT编程内存层级体系","slug":"SIMT编程内存层级体系","link":"#SIMT编程内存层级体系"},{"level":2,"title":"SIMT编程接口体系","slug":"SIMT编程接口体系","link":"#SIMT编程接口体系"},{"level":3,"title":"SIMT编程接口特点","slug":"SIMT编程接口特点","link":"#SIMT编程接口特点"},{"level":2,"title":"小结","slug":"小结","link":"#小结"}],"lastUpdated":1787050286000}'),d={name:"guide/programming_guide/programming_model/ai_core_simt_programming/overview.md"};function i(l,e,n,c,s,g){return t(),a("div",null,[...e[0]||(e[0]=[o('<div><article class="markdown-body"><h1>AI Core SIMT编程模型概述</h1><h2 id="引言">引言<a class="header-anchor" href="#引言">​</a></h2><p>SIMT（Single Instruction Multiple Thread，单指令多线程）编程是AI Core编程方式的一种重要补充，特别适用于离散数据访问、复杂控制逻辑和分支发散等场景。Ascend C支持与业界一致的SIMT编程模型，通过线程级并行实现数据并行计算，每个线程允许指令对数据进行独立寻址与计算，从而实现了更高的编程灵活性。本章将以<strong>SIMT编程模型</strong>为主线，遵循「宏观架构—线程调度—代码落地」的递进逻辑，完整覆盖SIMT算子开发全链路：阐述多线程并行架构的执行机制，拆解线程块内Warp调度的底层逻辑，并完成算子核函数（Kernel）计算逻辑的开发。</p><h2 id="异构并行计算核心模型：SIMT编程范式">异构并行计算核心模型：SIMT编程范式<a class="header-anchor" href="#异构并行计算核心模型：SIMT编程范式">​</a></h2><p>SIMT编程支持业界通用的线程架构：<strong>Grid-Block-Thread</strong>，以线程作为最小执行单元，通过大规模线程并发实现数据并行计算。所有SIMT算子的并行逻辑、数据拆分策略、线程调度机制，均基于该编程范式实现。</p><p><strong>三级线程层级</strong>：</p><ul><li><strong>网格（Grid）</strong>：由多个线程块（Thread Block）组成，使用内置变量<a href="../../language_extension/simt_builtin_keywords.html#li20760123812911">gridDim</a>表示启用的线程块个数，Grid维度通过dim3三维结构表示。</li><li><strong>线程块（Thread Block）</strong>：由若干线程组成，使用内置变量<a href="../../language_extension/simt_builtin_keywords.html#li076017381191">blockDim</a>表示一个线程块启用的线程个数（一个线程块最多可启用2048个线程）。各线程块通过线程块索引<a href="../../language_extension/simt_builtin_keywords.html#li1676053814914">blockIdx</a>进行标识。</li><li><strong>线程（Thread）</strong>：最小执行单位，每个线程拥有独立的寄存器，可通过线程索引<a href="../../language_extension/simt_builtin_keywords.html#li7760123814919">threadIdx</a>标识，负责完成特定的数据计算任务。</li></ul><p><strong>Warp调度机制</strong>：</p><p>每个线程块被切分成多个Warp依次调度执行，Warp是执行相同指令的线程集合，每个Warp包含32个线程。每个AIV核包含多个Warp调度器（Warp Scheduler），当某个Warp因全局内存访问处于阻塞状态时，Warp调度器会立刻切换到就绪的Warp，确保计算单元处于忙碌状态，从而掩盖访存的延迟并实现硬件利用率最大化。</p><blockquote><p>📌 <strong>提示</strong>：基于SIMT编程模型的程序，在AIV核上执行多个结构相同的线程块，执行的总线程数等于gridDim × blockDim。每个线程指向相同的代码逻辑，但处理不同的数据片段，实现数据并行。</p></blockquote><h2 id="硬件底层支撑：SIMT单元架构与内存层级">硬件底层支撑：SIMT单元架构与内存层级<a class="header-anchor" href="#硬件底层支撑：SIMT单元架构与内存层级">​</a></h2><p>向量处理单元<a href="../../advanced_programming/hardware_implementation/basic_architecture.html">AIV核</a>是SIMT编程的核心硬件载体，采用「Warp调度器 + 计算单元 + 分级存储体系」的架构，下文将详细介绍SIMT核心硬件组件及SIMT编程的内存层级体系。</p><h3 id="核心硬件组件">核心硬件组件<a class="header-anchor" href="#核心硬件组件">​</a></h3><ul><li><strong>Warp调度器</strong>：每个AIV核包含多个Warp调度器，负责线程块的切分与调度。Warp调度器将线程块划分为多个Warp，依次发射执行，实现高效的线程级并行调度。</li><li><strong>计算单元</strong>：AIV核内的向量计算单元，负责执行各类向量运算指令。同一Warp内的32个线程执行相同指令，但对不同数据地址进行操作，实现单指令多线程并行计算。</li><li><strong>寄存器文件</strong>：每个线程拥有独立的寄存器空间，用于存储局部变量和计算中间结果。寄存器数量受线程块内线程数量影响，线程数量越多，每个线程可用的寄存器数量越少。</li><li><strong>共享内存</strong>：线程块内所有线程共享的内存空间，位于AIV核内部，具有高带宽、低延迟特性，可作为用户管理的高速缓存，支持线程间数据交互。</li></ul><h3 id="SIMT编程内存层级体系">SIMT编程内存层级体系<a class="header-anchor" href="#SIMT编程内存层级体系">​</a></h3><p>SIMT线程可访问多种内存空间，形成「全局内存-共享内存-寄存器」三级内存层级，各层级作用域、生命周期与物理位置差异如下：</p><table><thead><tr><th>内存类型</th><th>线程作用域</th><th>内存修饰符</th><th>生命周期</th><th>物理位置</th><th>特点</th></tr></thead><tbody><tr><td><strong>全局内存</strong></td><td>Grid</td><td>__gm__</td><td>应用程序</td><td>Device</td><td>所有线程可直接访问，持久化存储</td></tr><tr><td><strong>共享内存（UB）</strong></td><td>Block</td><td>__ubuf__</td><td>核函数（Kernel）</td><td>AIV核</td><td>线程块内共享，高带宽低延迟</td></tr><tr><td><strong>寄存器</strong></td><td>Thread</td><td>NA</td><td>核函数（Kernel）</td><td>AIV核</td><td>线程私有，编译器管理，数量受blockDim影响</td></tr></tbody></table><h2 id="SIMT编程接口体系">SIMT编程接口体系<a class="header-anchor" href="#SIMT编程接口体系">​</a></h2><h3 id="SIMT编程接口特点">SIMT编程接口特点<a class="header-anchor" href="#SIMT编程接口特点">​</a></h3><p>SIMT编程接口遵循业界统一方式，开发者通过Ascend C提供的操作符和接口操作全局内存与共享内存，实现对硬件能力的完全控制，同时SIMT编程也提供部分高阶特性用于特定的应用场景，具体接口可以查询<a href="../../../../api/SIMT-API/SIMT-API.html">SIMT-API</a>。</p><p>SIMT编程接口核心特点：</p><ul><li><strong>内置关键字扩展</strong>：遵循业界统一方式，提供<code>__global__</code>修饰符以及<code>blockIdx</code>、<code>threadIdx</code>、<code>blockDim</code>、<code>gridDim</code>等线程索引变量。</li><li><strong>共享内存管理</strong>：支持与业界一致的使用方式，通过<code>__ubuf__</code>修饰符申请静态共享内存，支持动态内存申请方式。</li><li><strong>同步接口支持</strong>：支持与业界一致的同步方式，提供<code>asc_syncthreads</code>、<code>asc_threadfence</code>等同步接口，确保线程间数据访问正确性。</li><li><strong>Warp类接口支持</strong>：支持与业界一致的Warp类接口，提供<code>asc_shfl</code>、<code>asc_reduce_max</code>、<code>asc_all</code>等Warp类操作接口，用于直接操作线程束。</li><li><strong>原子操作支持</strong>：支持与业界一致的使用方式，提供<code>asc_atomic_add</code>、<code>asc_atomic_sub</code>、<code>asc_atomic_exch</code>等原子操作接口。</li><li><strong>数学函数支持</strong>：遵循业界统一方式，提供<code>sin</code>、<code>cos</code>、<code>exp</code>、<code>__brev</code>、<code>__clz</code>等计算接口，支持<code>half</code>、<code>half2</code>、<code>bfloat16_t</code>、<code>bfloat16x2_t</code>、<code>float</code>、<code>float2</code>等多种数据类型。</li><li><strong>高阶特性支持</strong>：当前提供协作组特性，用于需要灵活控制分组的业务场景。</li></ul><h2 id="小结">小结<a class="header-anchor" href="#小结">​</a></h2><p>本章系统阐述了SIMT算子从线程架构、硬件调度到代码落地的全链路技术体系：计算任务基于Grid-Block-Thread三级线程层级分发至AIV核并行执行，通过线程索引自动映射数据范围，实现大规模线程并发计算。开发者基于SIMT语言编程接口，通过指针操作全局内存与共享内存，配合同步机制确保线程间数据访问正确性。</p><p>后续章节将深入详解<a href="./abstract_hardware_architecture.html">抽象硬件架构</a>、<a href="./thread_architecture.html">线程架构</a>、<a href="./kernel_function.html">核函数（Kernel）</a>定义与调用、<a href="./memory_hierarchy.html">内存层级</a>管理机制、<a href="./synchronization.html">同步机制</a>原理、<a href="./atomic_operations.html">原子操作</a>使用方式、<a href="./programming_examples.html">编程示例</a>实战流程，帮助开发者快速理解核心技术，熟练掌握高性能、高可用的SIMT算子开发技术。</p></article></div>',1)])])}const m=r(d,[["render",i]]);export{h as __pageData,m as default};
